create table if not exists schedule_exact_oracle_runs(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),input_hash text not null,solver text not null default 'OR_TOOLS_CP_SAT',status text not null,objective numeric,best_bound numeric,gap numeric,wall_ms integer,unsupported jsonb not null default '[]'::jsonb,diagnostics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(status in('OPTIMAL','FEASIBLE','INFEASIBLE','UNKNOWN','UNSUPPORTED')));
create index if not exists idx_schedule_exact_oracle_runs_tenant_created on schedule_exact_oracle_runs(institution_code,created_at desc);
create or replace function get_schedule_exact_oracle_problem_v1() returns jsonb language sql stable security definer set search_path=public as $$with tp as(select to_jsonb(t) j from schedule_time_profiles t where t.active and tenant_row_allowed(t.institution_code) order by t.updated_at desc limit 1),a as(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',ta.id,'teacher_id',ta.teacher_id,'class_id',r.class_id,'course_id',r.course_id,'assigned_hours',ta.assigned_hours,'week_pattern',tm.week_pattern,'valid_from',tm.valid_from,'valid_to',tm.valid_to,'term_no',tm.term_no,'schedule_session_id',tm.schedule_session_id,'allowed_periods',tm.allowed_periods)),'[]'::jsonb) j from teacher_course_assignments ta join class_course_requirements r on r.id=ta.class_course_requirement_id join get_schedule_assignment_time_model_v1() tm on tm.assignment_id=ta.id where tenant_row_allowed(ta.institution_code)),l as(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',teacher_assignment_id,'weekday',weekday,'period',period)),'[]'::jsonb) j from teacher_schedule where active and locked and tenant_row_allowed(institution_code)),u as(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) j from teacher_unavailability x where active and tenant_row_allowed(institution_code)),pr as(select coalesce(jsonb_agg(jsonb_build_object('id',id,'relation_type',relation_type,'mode',mode,'weight',weight,'left_selector',left_selector,'right_selector',right_selector,'parameters',parameters)),'[]'::jsonb) j from schedule_planning_relations where active and mode<>'OFF' and tenant_row_allowed(institution_code)),sw as(select coalesce(jsonb_agg(jsonb_build_object('left_assignment_id',left_assignment_id,'right_assignment_id',right_assignment_id,'student_weight',student_weight,'severity_weight',severity_weight)),'[]'::jsonb) j from get_schedule_assignment_student_conflict_weights_v2()) select jsonb_build_object('schema','OKULOS_CP_SAT_ORACLE_V1','tenant',current_tenant_code(),'time_profile',coalesce((select j from tp),'{}'::jsonb),'assignments',(select j from a),'locked_rows',(select j from l),'teacher_unavailability',(select j from u),'planning_relations',(select j from pr),'student_conflict_weights',(select j from sw),'canonical_objective_order',jsonb_build_array('HARD','UNPLACED','MEDIUM','SOFT','LEGACY'))$$;
create or replace function record_schedule_exact_oracle_result_v1(p_input_hash text,p_status text,p_objective numeric default null,p_best_bound numeric default null,p_gap numeric default null,p_wall_ms integer default null,p_unsupported jsonb default '[]'::jsonb,p_diagnostics jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;begin perform open_permission_context('schedule.generate');if p_status not in('OPTIMAL','FEASIBLE','INFEASIBLE','UNKNOWN','UNSUPPORTED') then raise exception 'ORACLE_STATUS_INVALID';end if;if coalesce(length(p_input_hash),0)<16 then raise exception 'ORACLE_HASH_INVALID';end if;insert into schedule_exact_oracle_runs(input_hash,status,objective,best_bound,gap,wall_ms,unsupported,diagnostics) values(p_input_hash,p_status,p_objective,p_best_bound,p_gap,p_wall_ms,coalesce(p_unsupported,'[]'),coalesce(p_diagnostics,'{}')) returning id into rid;return rid;end$$;